use crate::game::bases::interface_call;
use crate::platform;

/// First word of this REL's BSS: head of the module-global state list.
///
/// `// observed:` every registrar passes its three-word node to
/// [`fn_80c00160`], which links it here; [`fn_80c00180`] walks and clears it.
const STATE_LIST_HEAD: usize = 0x80C6_C900;

/// `main.dol` constructor called as `(state, name)` before the descriptor copy.
///
/// `// inferred:` it initializes the state's name/id sub-object, because every
/// registrar calls it exactly once per state and passes the `StateID` string.
const STATE_NAME_CTOR: usize = 0x8015_F7C0;

/// Calls a no-argument function and keeps its `u32` return value.
///
/// `crate::platform::call0` intentionally models the void-call form and drops
/// the return register. The state-id factories in this module return a value
/// (`uVar10 = FUN_...();`), so this local shim preserves `r3` instead.
///
/// # Safety
/// `addr` must point to a function with the PowerPC EABI no-argument form.
///
/// # Confidence
/// high - mechanical ABI shim; the same pattern appears in other lanes.
unsafe fn call0_ret(addr: usize) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn() -> u32);
    f()
}

/// Copies the nine-word descriptor with the rotation observed in all 113 state
/// blocks.
///
/// The source is a contiguous 9-word table (`src + 0x00..+0x20`). The
/// destination state stores those words in the rotated order shown below. The
/// rotation is identical across all eight bosses, so it is implemented once.
///
/// # Safety
/// `src..src+0x24` must be readable and `dst+0x0C..dst+0x30` writable.
///
/// # Confidence
/// high - the same nine moves appear in every registrar block.
unsafe fn copy_state_descriptor(dst: usize, src: usize) {
    platform::write_u32(dst + 0x0C, platform::read_u32(src + 0x18));
    platform::write_u32(dst + 0x10, platform::read_u32(src + 0x1C));
    platform::write_u32(dst + 0x14, platform::read_u32(src + 0x20));
    platform::write_u32(dst + 0x18, platform::read_u32(src + 0x0C));
    platform::write_u32(dst + 0x1C, platform::read_u32(src + 0x10));
    platform::write_u32(dst + 0x20, platform::read_u32(src + 0x14));
    platform::write_u32(dst + 0x24, platform::read_u32(src + 0x00));
    platform::write_u32(dst + 0x28, platform::read_u32(src + 0x04));
    platform::write_u32(dst + 0x2C, platform::read_u32(src + 0x08));
}

/// Registers one boss state: name construction, descriptor copy, optional
/// state-id factory, then list insertion.
///
/// This is the body shared by the repeated block in every `StateID` registrar.
/// `callback_factory == 0` means the state has **no** `+0x30` field; the first
/// and last state families in several bosses use the 0x30-byte form, while the
/// middle action families use the 0x34-byte form.
///
/// The original orders the independent vtable/descriptor stores differently in
/// a few blocks; this helper always writes the vtable first, then the nine
/// descriptor words. Every store and every call is preserved.
///
/// # Safety
/// `state`, `desc` and `node` must point to the writable synthetic-BSS objects
/// named by their addresses; `name` and `callback_factory` must be readable
/// code/data addresses.
///
/// # Confidence
/// high - matches every one of the 113 observed blocks.
unsafe fn register_state(
    state: usize,
    desc: usize,
    vtable: usize,
    callback_factory: usize,
    runner: usize,
    node: usize,
    name: usize,
) {
    // The original evaluates the factory before constructing the state name.
    let callback_value = if callback_factory != 0 {
        call0_ret(callback_factory)
    } else {
        0
    };

    platform::call2(STATE_NAME_CTOR, state as u32, name as u32);
    platform::write_u32(state, vtable as u32);
    copy_state_descriptor(state, desc);

    if callback_factory != 0 {
        platform::write_u32(state + 0x30, callback_value);
    }

    fn_80c00160(state, runner, node);
}

