///
/// # Confidence
/// high - identical shape to the shared state destructor, exact callees.
pub unsafe fn fn_80c04c10(this: usize, free_it: i32) -> usize {
    if this != 0 {
        platform::call2(0x800A_8B10, this as u32, 0);
        if free_it > 0 {
            platform::call1(0x8016_2920, this as u32);
        }
    }
    this
}

