// ---------------------------------------------------------------------------
// Wave 3 shared helpers
// ---------------------------------------------------------------------------
//
// These are host-side shims for ABI shapes that `crate::platform` does not
// cover: floating-point arguments/returns, 64-bit reads, and the two-level
// vtable call pattern. They contain no game logic.

/// Reads one big-endian signed halfword.
///
/// # Safety
/// `addr..addr+2` must be readable in the target address space.
unsafe fn read_i16(addr: usize) -> i16 {
    platform::read_u16(addr) as i16
}

/// Reads one big-endian IEEE-754 double from two consecutive words.
///
/// # Safety
/// `addr..addr+8` must be readable in the target address space.
unsafe fn read_f64(addr: usize) -> f64 {
    let hi = platform::read_u32(addr) as u64;
    let lo = platform::read_u32(addr + 4) as u64;
    f64::from_bits((hi << 32) | lo)
}

/// Calls a function that takes one integer and returns a `f32` in `f1`.
///
/// # Safety
/// `addr` must point to a PowerPC EABI function with that prototype.
unsafe fn call_f32_1(addr: usize, a: u32) -> f32 {
    let f = crate::platform::guest_fn!(addr, fn(u32) -> f32);
    f(a)
}

/// Calls a function that takes one `f64` and returns `f64`.
///
/// # Safety
/// `addr` must point to a PowerPC EABI function with that prototype.
unsafe fn call_f64_ret(addr: usize, value: f64) -> f64 {
    let f = crate::platform::guest_fn!(addr, fn(f64) -> f64);
    f(value)
}

/// Calls a function shaped `(f64, u32)`.
///
/// # Safety
/// `addr` must point to a PowerPC EABI function with that prototype.
unsafe fn call_f64_1(addr: usize, value: f64, a: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f64, u32) -> u32);
    f(value, a)
}

/// Calls a function shaped `(f64, u32, u32)`.
///
/// # Safety
/// `addr` must point to a PowerPC EABI function with that prototype.
unsafe fn call_f64_2(addr: usize, value: f64, a: u32, b: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f64, u32, u32) -> u32);
    f(value, a, b)
}

/// Calls a function shaped `(f64, f64, f64, u32, u32, u32)`.
///
/// Used by the collision sweep at `0x8065C9A0`, whose first three arguments
/// the export promotes to `double`.
///
/// # Safety
/// `addr` must point to a PowerPC EABI function with that prototype.
unsafe fn call_fff_uuu(addr: usize, a: f64, b: f64, c: f64, d: u32, e: u32, f: u32) -> u32 {
    let func = crate::platform::guest_fn!(addr, fn(f64, f64, f64, u32, u32, u32) -> u32);
    func(a, b, c, d, e, f)
}

/// Reconstructs the PowerPC `0x43300000` integer-to-double conversion idiom.
///
/// The export writes `CONCAT44(0x43300000, value ^ 0x80000000)` and subtracts
/// the bias stored at `0x80C57CF0`. That produces the signed 32-bit `value` as
/// a `double` when the bias is `2^52 + 2^31`; the actual constant is read from
/// memory rather than assumed here.
///
/// # Safety
/// None; pure arithmetic.
unsafe fn int_to_double(value: u32, bias: f64) -> f64 {
    let low = (value ^ 0x8000_0000) as u64;
    f64::from_bits((0x4330_0000u64 << 32) | low) - bias
}

/// Calls vtable slot `slot` of the object whose vtable pointer lives at
/// `vtable_object`, with no arguments.
///
/// # Safety
/// `vtable_object` must hold a readable vtable pointer and the slot must be a
/// valid code address.
unsafe fn vcall0(vtable_object: usize, slot: usize) -> u32 {
    let vtable = platform::read_u32(vtable_object) as usize;
    let function = platform::read_u32(vtable + slot) as usize;
    call0_ret(function)
}

/// Calls vtable slot `slot` with one argument.
///
/// # Safety
/// As [`vcall0`]; the argument must match the slot's prototype.
unsafe fn vcall1(vtable_object: usize, slot: usize, a: u32) -> u32 {
    let vtable = platform::read_u32(vtable_object) as usize;
    let function = platform::read_u32(vtable + slot) as usize;
    platform::call1(function, a)
}

/// Calls vtable slot `slot` with two arguments.
///
/// # Safety
/// As [`vcall0`]; the arguments must match the slot's prototype.
unsafe fn vcall2(vtable_object: usize, slot: usize, a: u32, b: u32) -> u32 {
    let vtable = platform::read_u32(vtable_object) as usize;
    let function = platform::read_u32(vtable + slot) as usize;
    platform::call2(function, a, b)
}

/// Calls vtable slot `slot` with three arguments.
///
/// # Safety
/// As [`vcall0`]; the arguments must match the slot's prototype.
unsafe fn vcall3(vtable_object: usize, slot: usize, a: u32, b: u32, c: u32) -> u32 {
    let vtable = platform::read_u32(vtable_object) as usize;
    let function = platform::read_u32(vtable + slot) as usize;
    platform::call3(function, a, b, c)
}

/// Calls vtable slot `slot` with six arguments.
///
/// # Safety
/// As [`vcall0`]; the arguments must match the slot's prototype.
unsafe fn vcall6(
    vtable_object: usize,
    slot: usize,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
) -> u32 {
    let vtable = platform::read_u32(vtable_object) as usize;
    let function = platform::read_u32(vtable + slot) as usize;
    platform::call6(function, a, b, c, d, e, f)
}

