///
/// # Safety
/// `this` must be null or a valid controller object.
///
/// # Confidence
/// high - exact control flow and callees.
pub unsafe fn fn_80c04cc0(this: usize, free_it: i32) -> usize {
    if this != 0 {
        platform::call2(0x802D_7B20, this as u32, 0);
        if free_it > 0 {
            platform::call1(0x802B_9280, this as u32);
        }
    }
    this
}

// ---------------------------------------------------------------------------
// Action runners with a +0x360 state counter (0x80C2F0C0..0x80C32800)
// ---------------------------------------------------------------------------

/// Actor offset of the 32-bit action-state counter (`// inferred:`).
const ACTOR_STATE: usize = 0x360;
/// Actor offset of the animation object (`// inferred:`).
const ACTOR_ANIM: usize = 0x644;
/// Actor offset of the model object (`// inferred:`).
const ACTOR_MODEL: usize = 0x604;
/// Actor offset of the model root used for clip lookup (`// inferred:`).
const ACTOR_MODEL_ROOT: usize = 0x600;
/// Actor offset of the byte transition flag (`// inferred:`).
const ACTOR_FLAG_348: usize = 0x348;
/// Actor offset of position x (`// inferred:` from the jump math).
const ACTOR_POS_X: usize = 0xAC;
/// Actor offset of position y (`// inferred:`).
const ACTOR_POS_Y: usize = 0xB0;
/// Actor offset of position z (`// inferred:`).
const ACTOR_POS_Z: usize = 0xB4;
/// Actor offset of horizontal speed (`// inferred:`).
const ACTOR_SPEED_X: usize = 0xE8;
/// Actor offset of vertical velocity (`// inferred:`).
const ACTOR_VELOCITY_Y: usize = 0xEC;
/// Actor offset of per-frame vertical acceleration (`// inferred:`).
const ACTOR_ACCEL_Y: usize = 0x114;

/// Six-state action runner: jump start, jump loop, jump attack, landing,
/// damage reaction and end.
///
/// The state machine is driven by the counter at `+0x360`. Clips names observed
/// in the export: `jump_st`, `jumpA`, `jump_ed` and `clown_damage_up`.
///
/// # Original
/// Synthetic base `0x80C00000`; this address is not a runtime address.
/// `FUN_80c2f0c0`, address `0x80C2F0C0`, size 1,352 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c2f0c0_FUN_80c2f0c0.c`.
///
/// # Arguments
/// * `actor` - actor instance with the fields documented in the module's
///   action-runner data model.
///
/// # Side effects
/// Per frame: updates the model vtable slot `+0x1C`, applies gravity/velocity
/// to `+0xE8/+0xEC`, plays clips through `0x801651F0`/`0x80169F80`, changes the
/// meshes through `0x8016A0F0`, and increments the state counter.
///
/// # Safety
/// `actor` must be a live actor whose vtable fields and model/animation objects
/// are initialized.
///
/// # Confidence
/// medium - every store, branch and constant address is exact; the C export was
/// compiled from paired-single code and the motion constants are read from
/// memory because their numeric values are not in the export.
pub unsafe fn fn_80c2f0c0(actor: usize) {
    let a = actor as u32;
    let model = actor + ACTOR_MODEL;
    let anim = actor + ACTOR_ANIM;
    let root = actor + ACTOR_MODEL_ROOT;

    // observed: per-frame virtual model update before the state dispatch.
    vcall1(model, 0x1C, model as u32);

    match platform::read_i32(actor + ACTOR_STATE) {
        1 => {
            platform::call1(0x8006_CDE0, a);
            platform::call1(0x8009_55F0, a);
            if platform::call1(0x8007_2BC0, a + 0x1EC) != 0 {
                platform::write_f32(actor + ACTOR_VELOCITY_Y, platform::read_f32(0x80C5_7F74));
            }
            if platform::call1(0x8016_9020, anim as u32) != 0 {
                let mut clip = crate::platform::GuestLocal::new( platform::call2(0x8023_A0B0, root as u32, 0x80C6_3A64));
                platform::call4(
                    0x8016_51F0,
                    anim as u32,
                    model as u32,
                    (clip.as_mut_ptr() as *mut u32) as u32,
                    0,
                );
                call_f64_2(
                    0x8016_9F80,
                    platform::read_f32(0x80C5_7FCC) as f64,
                    model as u32,
                    anim as u32,
                );
                call_f64_1(
                    0x8016_80E0,
                    platform::read_f32(0x80C5_7F84) as f64,
                    anim as u32,
                );
                platform::write_u8(actor + ACTOR_FLAG_348, 0);
                platform::write_u32(actor + ACTOR_STATE, 2);
            }
        }
        2 => {
            platform::call1(0x8006_CDE0, a);
            platform::call1(0x8009_55F0, a);
            if platform::call1(0x8007_2BC0, a + 0x1EC) != 0 {
                platform::write_f32(actor + ACTOR_VELOCITY_Y, platform::read_f32(0x80C5_7F74));
            }
            let index = platform::read_u8(actor + ACTOR_FLAG_348) as usize;
            // observed: 0x8042C1A4 is a signed-halfword table selected by the
            // byte at +0x348; the table's meaning is unknown.
            let angle = read_i16(0x8042_C1A4 + index * 2) as i32;
            if platform::call3(0x8015_F4F0, a + 0x102, angle as u32, 0xA00) != 0 {
                let mut clip = crate::platform::GuestLocal::new( platform::call2(0x8023_A0B0, root as u32, 0x80C6_3A70));
                platform::call4(
                    0x8016_51F0,
                    anim as u32,
                    model as u32,
                    (clip.as_mut_ptr() as *mut u32) as u32,
                    1,
                );
                call_f64_2(
                    0x8016_9F80,
                    platform::read_f32(0x80C5_7FCC) as f64,
                    model as u32,
                    anim as u32,
                );
                call_f64_1(
                    0x8016_80E0,
                    platform::read_f32(0x80C5_7F84) as f64,
                    anim as u32,
                );
                platform::write_u32(actor + ACTOR_STATE, 3);
            }
        }
        3 => {
            platform::call1(0x8006_CDE0, a);
            platform::call1(0x8009_55F0, a);
            if platform::call1(0x8007_2BC0, a + 0x1EC) != 0 {
                platform::write_f32(actor + ACTOR_VELOCITY_Y, platform::read_f32(0x80C5_7F74));
            }
            if platform::call1(0x8016_9020, anim as u32) != 0 {
                let mut clip = crate::platform::GuestLocal::new( platform::call2(0x8023_A0B0, root as u32, 0x80C6_3A78));
                platform::call4(
                    0x8016_51F0,
                    anim as u32,
                    model as u32,
                    (clip.as_mut_ptr() as *mut u32) as u32,
                    1,
                );
                call_f64_2(
                    0x8016_9F80,
                    platform::read_f32(0x80C5_7FCC) as f64,
                    model as u32,
                    anim as u32,
                );
                call_f64_1(
                    0x8016_80E0,
                    platform::read_f32(0x80C5_7F84) as f64,
                    anim as u32,
                );

                platform::write_f32(actor + ACTOR_VELOCITY_Y, platform::read_f32(0x80C5_7F40));
                let holder = vcall1(actor + 0x60, 0x3F4, a);
                let mut target = crate::platform::GuestLocal::new( [0f32; 3]);
                platform::call2(
                    0x800A_4270,
                    target.as_mut_ptr() as u32,
                    holder,
                );
                // observed: the export adds DAT_80c57f4c to the target x.
                let target_x = target[0] + platform::read_f32(0x80C5_7F4C);
                let target_y = target[1];

                let floor = platform::read_f32(0x80C5_7F74);
                let step = platform::read_f32(0x80C5_7F84);
                platform::write_f32(actor + 0xD74, floor);
                let mut velocity = platform::read_f32(actor + ACTOR_VELOCITY_Y);
                let mut y = platform::read_f32(actor + ACTOR_POS_Y);
                while target_y <= y || floor <= velocity {
                    velocity += platform::read_f32(actor + ACTOR_ACCEL_Y);
                    y += velocity;
                    let elapsed = platform::read_f32(actor + 0xD74) + step;
                    platform::write_f32(actor + 0xD74, elapsed);
                }
                platform::write_f32(
                    actor + ACTOR_SPEED_X,
                    (target_x - platform::read_f32(actor + ACTOR_POS_X))
                        / platform::read_f32(actor + 0xD74),
                );

                platform::call1(0x8009_C810, a);
                vcall3(actor + 0x544, 0x24, a + 0x544, 0x59E, 0);
                vcall3(actor + 0x544, 0x24, a + 0x544, 0x4E5, 0);
                platform::write_u32(actor + ACTOR_STATE, 4);
            }
        }
        4 => {
            platform::call1(0x8009_C860, a);
            platform::call1(0x8006_CDE0, a);
            platform::call1(0x8009_55F0, a);

            let holder = vcall1(actor + 0x60, 0x3F4, a);
            let mut target = crate::platform::GuestLocal::new( [0f32; 3]);
            platform::call2(0x800A_4270, target.as_mut_ptr() as u32, holder);
            if platform::read_f32(actor + ACTOR_POS_Y) < target[1]
                && platform::read_f32(actor + ACTOR_VELOCITY_Y) < platform::read_f32(0x80C5_7F74)
            {
                let mut clip = crate::platform::GuestLocal::new( platform::call2(0x8023_A0B0, root as u32, 0x80C6_3A80));
                platform::call4(
                    0x8016_51F0,
                    anim as u32,
                    model as u32,
                    (clip.as_mut_ptr() as *mut u32) as u32,
                    1,
                );
                call_f64_2(
                    0x8016_9F80,
                    platform::read_f32(0x80C5_7FCC) as f64,
                    model as u32,
                    anim as u32,
                );
                call_f64_1(
                    0x8016_80E0,
                    platform::read_f32(0x80C5_7F84) as f64,
                    anim as u32,
                );

                let floor = platform::read_f32(0x80C5_7F74);
                platform::write_f32(actor + ACTOR_SPEED_X, floor);
                platform::write_f32(actor + ACTOR_VELOCITY_Y, floor);
                platform::write_u32(actor + ACTOR_POS_X, target[0].to_bits());
                platform::write_u32(actor + ACTOR_POS_Y, target[1].to_bits());
                platform::write_u32(actor + ACTOR_POS_Z, target[2].to_bits());
                platform::call3(0x8016_A0F0, model as u32, 1, 1);
                platform::write_u32(actor + 0x7AC, 1);

                let holder = vcall1(actor + 0x60, 0x3F4, a);
                vcall2((holder as usize) + 0x60, 0xD4, holder, 0x8035_7E1C);
                platform::write_u32(actor + ACTOR_STATE, 5);
            }
        }
        5 => {
            let holder = vcall1(actor + 0x60, 0x3F4, a);
            if platform::call1(0x8016_9020, holder + 0x584) != 0 {
                platform::call3(0x8016_A0F0, model as u32, 1, 0);
                let mut clip = crate::platform::GuestLocal::new( platform::call2(0x8023_A0B0, root as u32, 0x80C6_3A88));
                platform::call4(
                    0x8016_51F0,
                    anim as u32,
                    model as u32,
                    (clip.as_mut_ptr() as *mut u32) as u32,
                    1,
                );
                call_f64_2(
                    0x8016_9F80,
                    platform::read_f32(0x80C5_7F74) as f64,
                    model as u32,
                    anim as u32,
                );
                call_f64_1(
                    0x8016_80E0,
                    platform::read_f32(0x80C5_7F84) as f64,
                    anim as u32,
                );
                call_f64_1(
                    0x8016_8FE0,
                    platform::read_f32(0x80C5_7FCC) as f64,
                    anim as u32,
                );
                platform::write_u8(actor + ACTOR_FLAG_348, 1);
                // observed: the 16-bit selector is copied from 0x8042C1A6.
                platform::write_u16(actor + 0x102, platform::read_u16(0x8042_C1A6));
                platform::call2(0x8009_BFD0, a, 0);
                platform::write_u32(actor + ACTOR_STATE, 6);
            }
        }
        6 => {
            if platform::call1(0x8016_9020, anim as u32) != 0 {
                platform::write_u32(actor + ACTOR_STATE, 7);
                vcall2(actor + 0x60, 0xD4, a, 0x80C6_F374);
            }
        }
        _ => {}
    }
}

