    platform::write_f32(actor + 0xE7C, y);
    platform::write_u32(actor + 0xE80, z);
    platform::write_f32(actor + 0xE84, x - platform::read_f32(0x80C5_8594));
    platform::write_f32(actor + 0xE88, platform::read_f32(0x80C5_8598) + y);

