    platform::write_u32(actor + 0xE98, marker);
    platform::write_u32(actor + 0xE94, marker);
    platform::write_u32(actor + 0xEA0, marker);
    platform::write_u32(actor + 0xE9C, marker);
    platform::write_u32(actor + 0xEA8, marker);
    platform::write_u32(actor + 0xEA4, marker);
    platform::write_u32(actor + 0xEB4, marker);
    platform::write_u32(actor + 0xEB0, marker);
    platform::write_u32(actor + 0xEAC, marker);
    platform::write_u16(actor + 0xEB8, 0);

    platform::call2(0x8016_A000, (actor + 0x604) as u32, (actor + 0xEBC) as u32);

    let base = platform::read_u32(0x80C5_859C);
    let light = platform::read_u32(0x80C5_85A0);
    let mid = platform::read_u32(0x80C5_85A4);
    let other = platform::read_u32(0x80C5_85A8);
    let tail = platform::read_u32(0x80C5_85AC);
    let table_a = platform::read_u32(0x8042_BB08);
    let table_b = platform::read_u32(0x8042_BB0C);

    platform::write_u32(actor + 0xDC, light);
    platform::write_u32(actor + 0xE0, light);
    platform::write_u32(actor + 0xE4, light);
    platform::write_u32(actor + 0x320, base);
    platform::write_u32(actor + 0x324, mid);
    platform::write_u32(actor + 0x318, other);
    platform::write_u32(actor + 0x31C, mid);
    platform::write_u32(actor + 0x328, table_a);
    platform::write_u32(actor + 0x32C, table_b);
    platform::write_u32(actor + 0xD0, base);
    platform::write_u32(actor + 0xD4, tail);
    platform::write_u32(actor + 0xD8, base);

