    platform::write_u32(actor + 0x754, 0x80C6_5F60); // &PTR_s_jump_st...
    platform::write_u32(actor + 0x758, 0x80C6_5FD4); // &PTR_s_throw_st...
    platform::write_u32(actor + 0x75C, 0x80C6_6038); // &PTR_s_damage...
    platform::write_u32(actor + 0x760, 0x80C6_60D0); // &PTR_DAT_80c660d0
    platform::write_f32(actor + 0x844, -scaled as f32);

