    platform::write_u32(actor + 0x164, platform::read_u32(0x80C6_632C));
    platform::write_u32(actor + 0x168, platform::read_u32(0x80C6_6330));
    platform::write_u32(actor + 0x16C, platform::read_u32(0x80C6_6334));
    platform::write_u32(actor + 0x170, platform::read_u32(0x80C6_6338));
    platform::call1(0x8008_C330, (actor + 0x148) as u32);

    platform::call5(
        0x8006_D090,
        (actor + 0x1EC) as u32,
        actor as u32,
        0x80C5_84D0,
        0x80C5_84C0,
        0x80C5_84E8,
    );
    platform::call5(
        0x8007_57B0,
        (actor + 0xAC) as u32,
        (actor + 0xE90) as u32,
        0,
        1,
        0xFFFF_FFFF,
    );

    platform::write_u32(actor + 0xB4, platform::read_u32(0x80C5_85C0));

    let created = vcall2(actor + 0x60, 0x654, actor as u32, 0);
    platform::write_u32(actor + 0xE74, created);

    let child = vcall1(actor + 0x60, 0x658, actor as u32) as usize;
