    platform::write_u32(actor + 0xAF0, 0x80C5_8540); // s_Wm_le_shelltail
    platform::write_u32(actor + 0xE6C, 0x80C6_6238);
    platform::write_u32(actor + 0xAD4, 0);
    platform::write_f32(
        actor + 0xB0,
        platform::read_f32(actor + 0xB0)
            + (platform::read_f32(0x80C5_85C4) as f64 * child_value) as f32,
    );
    platform::write_u32(actor + 0xAD0, 0);

