        vcall2(actor + 0x544, 0x24, (actor + 0x544) as u32, 0x512);
        platform::write_u8(actor + 0x348, platform::read_u8(actor + 0x348) ^ 1);
        platform::write_f32(actor + 0xE8, -platform::read_f32(actor + 0xE8));
        platform::write_f32(actor + 0xF4, -platform::read_f32(actor + 0xF4));
