/// Plays the movement-dependent `Wm_mo_drop` sound/effect and the landing
/// effect for the Morton actor.
///
/// # Original
/// Synthetic base `0x80C00000`; this address is not a runtime address.
/// `FUN_80c43d10`, address `0x80C43D10`, size 380 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c43d10_FUN_80c43d10.c`.
///
/// # Arguments
/// * `actor` - actor with the effect table at `+0xAF0`, the two effect vtables
///   at `+0xC1C`/`+0xD44`, the shared position at `+0xAE4`, the horizontal
///   speed at `+0xE8` and the vertical speed at `+0xF4`.
/// * `flag` - non-zero enables the second (sound) branch.
///
/// # Side effects
/// Dispatches table entries `+0x28`/`+0x2C` or `+0x28`, then `+0x30`/`+0x34`,
/// then `+0x38` through the `+0xA0` slot of the two effect objects. The
/// threshold for both speed tests is `0x80C58B00`.
///
/// # Safety
/// The table and both effect objects must be valid.
///
/// # Confidence
/// medium - control flow and offsets are exact; the table fields and vtable
/// slots are named by position only.
pub unsafe fn fn_80c43d10(actor: usize, flag: i32) {
    let table = platform::read_u32(actor + 0xAF0) as usize;
    let threshold = platform::read_f32(0x80C5_8B00);
    let speed = platform::read_f32(actor + 0xE8);

    if speed <= threshold {
        if speed < threshold && platform::read_i32(table + 0x28) != 0 {
            vcall6(
                actor + 0xC1C,
                0xA0,
                (actor + 0xC1C) as u32,
                platform::read_u32(table + 0x2C),
                0,
                (actor + 0xAE4) as u32,
                0,
                0,
            );
        }
    } else {
        let effect = platform::read_i32(table + 0x28);
        if effect != 0 {
            vcall6(
                actor + 0xC1C,
                0xA0,
                (actor + 0xC1C) as u32,
                effect as u32,
                0,
                (actor + 0xAE4) as u32,
                0,
                0,
            );
        }
    }

    if flag != 0 {
        let sound = platform::read_i32(table + 0x30);
        if platform::read_f32(actor + 0xF4) < threshold {
            if sound != 0 {
                platform::call5(
                    0x8016_C890,
                    platform::read_u32(table + 0x34),
                    0,
                    (actor + 0xAE4) as u32,
                    0,
                    0,
                );
            }
        } else if sound != 0 {
            platform::call5(
                0x8016_C890,
                sound as u32,
                0,
                (actor + 0xAE4) as u32,
                0,
                0,
            );
        }
    }

    let effect = platform::read_i32(table + 0x38);
    if effect != 0 {
        vcall6(
            actor + 0xD44,
            0xA0,
            (actor + 0xD44) as u32,
            effect as u32,
            0,
            (actor + 0xAE4) as u32,
            0,
            0,
        );
    }
}

