    let mut clip_word = crate::platform::GuestLocal::new( [clip]);
    platform::call4(
        0x8016_51F0,
        (actor + 0x644) as u32,
        (actor + 0x604) as u32,
        clip_word.as_mut_ptr() as u32,
        0,
    );
    call_f64_2(
        0x8016_9F80,
        platform::read_f32(0x80C5_8F78) as f64,
        (actor + 0x604) as u32,
        (actor + 0x644) as u32,
    );
    call_f64_1(
        0x8016_80E0,
        platform::read_f32(0x80C5_8F74) as f64,
        (actor + 0x644) as u32,
    );

    let damage = platform::call2(0x8023_A200, (actor + 0x600) as u32, 0x80C6_AB78);
    let mut damage_word = crate::platform::GuestLocal::new( [damage]);
    platform::write_u32(actor + 0x6A8, damage);
    platform::call5(
        0x8016_6BD0,
        (actor + 0x6AC) as u32,
        (actor + 0x604) as u32,
        damage_word.as_mut_ptr() as u32,
        0,
        0,
    );
    call_f64_2(
        0x8016_9F80,
        platform::read_f32(0x80C5_8F78) as f64,
        (actor + 0x604) as u32,
        (actor + 0x6AC) as u32,
    );
    call_f64_2(
        0x8016_6F10,
        platform::read_f32(0x80C5_8F74) as f64,
        (actor + 0x6AC) as u32,
        0,
    );

    platform::write_u8(actor + 0x432, 0);
    vcall1(actor + 0x60, 0x98, actor as u32);

    let speed = platform::read_u32(0x80C5_8F78);
    platform::write_u32(actor + 0xE8, speed);
    platform::write_u32(actor + 0xEC, platform::read_u32(0x80C5_8FF0));
    platform::write_u32(actor + 0xF0, speed);

    let side = platform::call2(0x8009_6240, actor as u32, (actor + 0xAC) as u32) as u8;
    platform::write_u8(actor + 0x348, side);
    let heading = read_i16(0x8042_C1A4 + side as usize * 2);
    platform::write_u16(actor + 0x102, heading as u16);
    platform::write_u32(actor + 0x794, 1);
