// Wave 6: boss constructors, damage entries, castle aim/fire handlers
// (0x80C07870..0x80C4A940)
// ---------------------------------------------------------------------------
//
// This pass follows the boss-family call graph rather than an address sample:
// the six per-boss actor constructors, the `damage`/`damage_s` entries that
// their state tables install, the Koopa shout/death phases, the two castle
// aim/fire scripts and the dispatcher that drives both aim solvers, three
// heading helpers, and the `Wm_ob_witchcraft` spawner that the wave-5 landing
// handler `0x80C08DC0` called by raw address.

/// Calls `(f64, f64, u32, u32, u32, u32)`, the shape of `0x800E7970`.
///
/// The export promotes the first two arguments to `double` and passes four
/// integer/pointer words.
///
/// # Safety
/// `addr` must point to a PowerPC EABI function with that prototype.
unsafe fn call_ff_uuuu(addr: usize, a: f64, b: f64, c: u32, d: u32, e: u32, f: u32) -> u32 {
    let func = crate::platform::guest_fn!(addr, fn(f64, f64, u32, u32, u32, u32) -> u32);
    func(a, b, c, d, e, f)
}

/// Calls `(f64, f64, u32, u32, u32, u32, u32)`, the shape of `0x800E79F0`.
///
/// # Safety
/// `addr` must point to a PowerPC EABI function with that prototype.
unsafe fn call_ff_uuuuu(
    addr: usize,
    a: f64,
    b: f64,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
    g: u32,
) -> u32 {
    let func = crate::platform::guest_fn!(addr, fn(f64, f64, u32, u32, u32, u32, u32) -> u32);
    func(a, b, c, d, e, f, g)
}

/// Calls vtable slot `slot` with four arguments.
///
/// # Safety
/// `vtable_object` must hold a readable vtable pointer and the slot must be a
/// valid code address whose prototype takes four integer/pointer words.
unsafe fn vcall4(vtable_object: usize, slot: usize, a: u32, b: u32, c: u32, d: u32) -> u32 {
    let vtable = platform::read_u32(vtable_object) as usize;
    let function = platform::read_u32(vtable + slot) as usize;
    platform::call4(function, a, b, c, d)
}

/// Calls vtable slot `slot` with one argument and returns the `f64` in `f1`.
///
/// # Safety
/// `vtable_object` must hold a readable vtable pointer and the slot must be a
/// valid code address with that prototype.
unsafe fn vcall_f64_arg1(vtable_object: usize, slot: usize, a: u32) -> f64 {
    let vtable = platform::read_u32(vtable_object) as usize;
    let function = platform::read_u32(vtable + slot) as usize;
    let f = crate::platform::guest_fn!(function, fn(u32) -> f64);
    f(a)
}

