/// Per-frame castle-boss phase dispatcher.
///
/// Phase 0 copies the ten entry positions from `0x80C61480` (three words
/// apart) into the sub-objects at `+0xF94` (stride 0xA4), storing only the
/// x/y offsets from the actor. Phase 1 ticks the auxiliary objects at `+0x6D4`
/// and `+0x67C`, runs [`fn_80c22ca0`], selects a target with [`fn_80c23cd0`], and
/// clamps the approach distance at `+0x71C` against
/// `0x80C61C1C`/`0x80C61C2C`. Every phase then runs class slot `+0x390`, both
/// aim solvers [`fn_80c23680`]/[`fn_80c239c0`], increments the frame counter
/// `+0x710`, and increments the `0x80C617F8` per-slot counters at `+0xF98`.
///
/// # Original
/// Synthetic base `0x80C00000`; this address is not a runtime address.
/// `FUN_80c21fe0`, address `0x80C21FE0`, size 760 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c21fe0_FUN_80c21fe0.c`.
/// - Removed: the modelled `_savegpr_26` prologue call (`0x802DCD70`) and the
///   `_restgpr_26` epilogue call (`0x802DCDBC`); the image reads the boss from
///   the incoming `r3` (`mr r31,r3`) and the tail `li r3,1` is the return.
///
/// # Arguments
/// * `actor` - the boss manager; the incoming `r3`.
///
/// # Side effects
/// Sub-object position writes, auxiliary updates, target tracking, both aim
/// solvers, per-slot counter increments, and the tail returns `1`.
///
/// # Safety
/// The manager, its `+0xF94` array and the selected target must be valid.
///
/// # Confidence
/// medium - all stores and branches are exact; the export unrolls the final
/// counter loop by eight (the Rust loop is store-for-store equivalent), and
/// the missing `0x8006CED0` argument is not used here.
pub unsafe fn fn_80c21fe0(actor: usize) -> u32 {
    vcall1(actor + 0x394, 0x10, (actor + 0x394) as u32);

    let entry_count = platform::read_i32(0x80C6_147C);
    if platform::read_i32(actor + 0x76C) == 0 {
        let mut index = 0i32;
        let mut offset = 0usize;
        while index < entry_count {
            let mut position = crate::platform::GuestLocal::new( [0f32; 3]);
            platform::call4(
                0x800E_7880,
                position.as_mut_ptr() as u32,
                (actor + 0x604) as u32,
                platform::read_u32(0x80C6_1480 + index as usize * 12),
                0x8037_7DC8,
            );

            let sub = platform::read_u32(actor + 0xF94) as usize + offset;
            platform::write_f32(sub + 0x1C, position[0] - platform::read_f32(actor + 0xAC));
            platform::write_f32(sub + 0x20, position[1] - platform::read_f32(actor + 0xB0));

            index += 1;
            offset += 0xA4;
        }
    }

    if platform::read_i32(actor + 0x76C) == 1 {
        vcall1(actor + 0x6D4, 0x14, (actor + 0x6D4) as u32);
        vcall1(actor + 0x67C, 0x14, (actor + 0x67C) as u32);
        fn_80c22ca0(actor);

        let target = fn_80c23cd0(actor) as usize;
        if target != 0 {
            let slot = platform::read_i32(actor + 0x770) as usize * 4;
            let mut limit = platform::read_f32(actor + slot + 0x758);
            let target_x = platform::read_f32(target + 0xAC);
            let candidate = target_x + platform::read_f32(0x80C6_1C2C + slot);
            if limit < candidate {
                limit = candidate;
            }

            if platform::read_u8(actor + 0x718) == 0 {
                if platform::read_f32(0x80C6_1C1C + slot)
                    < target_x - platform::read_f32(actor + 0xAC)
                    && platform::read_i32(actor + 0x774) != 4
                    && platform::read_i32(actor + 0x774) != 5
                {
                    platform::write_f32(actor + 0x71C, limit);
                    platform::write_u8(actor + 0x718, 1);
                    platform::write_u32(actor + 0x774, 3);
                }
            } else {
                let current = platform::read_f32(actor + 0x71C);
                platform::write_f32(actor + 0x71C, if current < limit { limit } else { current });
            }
        }
    }

    vcall1(actor + 0x60, 0x390, actor as u32);
    fn_80c23680(actor);
    fn_80c239c0(actor);

    platform::write_u32(
        actor + 0x710,
        platform::read_u32(actor + 0x710) + 1,
    );

    // observed: the export unrolls this by eight and then runs the remainder;
    // the ascending word writes are identical.
    let counter_count = platform::read_i32(0x80C6_17F8);
    let mut index = 0i32;
    while index < counter_count {
        let address = actor + 0xF98 + index as usize * 4;
        platform::write_u32(address, platform::read_u32(address) + 1);
        index += 1;
    }

    1
}

