///
/// # Confidence
/// high - the compound condition is copied literally.
pub unsafe fn fn_80c27400(value: usize, low: usize, high: usize) -> i32 {
    let sample = read_i16(value) as i32;
    let first = read_i16(low) as i32;
    let second = read_i16(high) as i32;

    if (((second <= first) || (sample < first)) || (second < sample))
        && (((first <= second) || (first < sample)) || (sample < second))
    {
        sample
    } else {
        first
    }
}

