/// `work/ghidra/rel-d_en_bossNP/export/80c0b440_FUN_80c0b440.c`.
///
/// # Arguments
/// * `x` - world x as a double.
/// * `actor` - owner of the three rig pointers.
///
/// # Returns
/// `0`, `1` or `2` for the closest rig, using the same abs/bound idiom as the
/// export.
///
/// # Side effects
/// Reads only.
///
/// # Safety
/// The three rig pointers must be live.
///
/// # Confidence
/// high - the three-distance selection is literal.
pub unsafe fn fn_80c0b440(x: f64, actor: usize) -> u8 {
    let zero = platform::read_f32(0x80C5_7474);

    let first = platform::read_u32(actor + 0x1140) as usize;
    let mut delta = x as f32 - platform::read_f32(first + 0xAC);
    if delta <= zero {
        delta = -delta;
    }
    let mut best = platform::read_f32(0x80C5_74A8);
    if delta < platform::read_f32(0x80C5_74A8) {
        best = delta;
    }

    let second = platform::read_u32(actor + 0x1144) as usize;
    let mut delta = x as f32 - platform::read_f32(second + 0xAC);
    if delta <= zero {
        delta = -delta;
    }
    let mut index = (delta < best) as u8;
    if index != 0 {
        best = delta;
    }

    let third = platform::read_u32(actor + 0x1148) as usize;
    let mut delta = x as f32 - platform::read_f32(third + 0xAC);
    if delta <= zero {
        delta = -delta;
    }
    if delta < best {
        index = 2;
    }
    index
}

/// Spawns the `Wm_ob_witchcraftup` effect and starts its scale animation.
///
/// The spawn position is `(+0x1118, +0x111C + 0x80C57480 * 0x80C5B8D0,
/// +0x1120)`. The phase-effect object at `+0x11BC` receives the name through
/// slot `+0xA0`, three scale words through slot `+0x74`, and the blend value
/// `0x80C5B8CC` through slot `+0x2C`.
///
/// # Original
/// Synthetic base `0x80C00000`; this address is not a runtime address.
/// `FUN_80c0b520`, address `0x80C0B520`, size 232 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c0b520_FUN_80c0b520.c`.
///
/// # Arguments
/// * `actor` - owner of the effect object at `+0x11BC`.
///
/// # Side effects
/// Spawns and configures the effect.
///
/// # Safety
/// `actor+0x11BC` must be a live effect object.
///
/// # Confidence
/// high - mirrors the translated [`fn_80c07870`] with a different name,
/// position source and scale table.
pub unsafe fn fn_80c0b520(actor: usize) {
    let mut position = crate::platform::GuestLocal::new( [
        platform::read_u32(actor + 0x1118),
        (platform::read_f32(actor + 0x111C)
            + platform::read_f32(0x80C5_7480) * platform::read_f32(0x80C5_B8D0))
        .to_bits(),
        platform::read_u32(actor + 0x1120),
    ]);
    vcall6(
        actor + 0x11BC,
        0xA0,
        (actor + 0x11BC) as u32,
        0x80C5_B944, // s_Wm_ob_witchcraftup
        0,
        position.as_mut_ptr() as u32,
        0,
        0,
    );

    let mut scale = crate::platform::GuestLocal::new( [
        platform::read_u32(0x80C5_74AC),
        platform::read_u32(0x80C5_74B0),
        platform::read_u32(0x80C5_74B0),
    ]);
    vcall4(
        actor + 0x11BC,
        0x74,
        (actor + 0x11BC) as u32,
        scale.as_mut_ptr() as u32,
        0,
        3,
    );
    vcall_f64_2(
        actor + 0x11BC,
        0x2C,
        platform::read_f32(0x80C5_B8CC) as f64,
        (actor + 0x11BC) as u32,
        3,
    );
}

/// Plays `jump_HB2` and launches the actor from a randomly chosen rig.
///
/// # Original
/// Synthetic base `0x80C00000`; this address is not a runtime address.
/// `FUN_80c0b810`, address `0x80C0B810`, size 220 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c0b810_FUN_80c0b810.c`.
///
/// # Arguments
/// * `actor` - actor with model `+0x604`, animation `+0x644` and rigs
///   `+0x1140..+0x1148`.
///
/// # Side effects
/// Binds the clip, stores the `0x800B2ED0(3)` slot at `+0x1134`, copies the
/// selected rig's x into `+0xAC`, writes the launch height `+0xB0`, zeroes
/// horizontal speed and sets the vertical limit `+0xF8`.
///
/// # Safety
/// The rig array and animation must be initialized.
///
/// # Confidence
/// high - offsets, constants and store order are exact.
pub unsafe fn fn_80c0b810(actor: usize) {
    let clip = platform::call2(0x8023_A0B0, (actor + 0x600) as u32, 0x80C5_B964);
    let mut args = crate::platform::GuestLocal::new( [clip]);
    platform::call4(
        0x8016_51F0,
        (actor + 0x644) as u32,
        (actor + 0x604) as u32,
        args.as_mut_ptr() as u32,
        0,
    );
    call_f64_2(
        0x8016_9F80,
        platform::read_f32(0x80C5_74A4) as f64,
        (actor + 0x604) as u32,
        (actor + 0x644) as u32,
    );
    call_f64_1(
        0x8016_80E0,
        platform::read_f32(0x80C5_74B0) as f64,
        (actor + 0x644) as u32,
    );

    let slot = platform::call1(0x800B_2ED0, 3) as u8;
    platform::write_u8(actor + 0x1134, slot);
    let rig = platform::read_u32(actor + (slot as i8 as usize) * 4 + 0x1140) as usize;
    platform::write_u32(actor + 0xAC, platform::read_u32(rig + 0xAC));
    platform::write_f32(
        actor + 0xB0,
        platform::read_f32(actor + 0x113C) + platform::read_f32(0x80C5_B860),
    );

    let zero = platform::read_u32(0x80C5_7474);
    platform::write_u32(actor + 0xE8, zero);
    platform::write_f32(actor + 0x114, -platform::read_f32(0x80C5_B854));
    platform::write_u32(actor + 0xEC, zero);
    platform::write_u32(actor + 0xF8, platform::read_u32(0x80C5_74C0));
}

/// Per-frame descent handler; leaves when the actor reaches the floor line.
///
/// # Original
/// Synthetic base `0x80C00000`; this address is not a runtime address.
/// `FUN_80c0b900`, address `0x80C0B900`, size 224 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c0b900_FUN_80c0b900.c`.
///
/// # Arguments
/// * `actor` - actor with model `+0x604`, class `+0x60` and controller
///   `+0x544`.
///
/// # Side effects
/// Updates model/physics, calls `0x800AA620` with class slot `+0x4C4`, plays
/// clip `0x581` through controller slot `+0x28`, and calls class slot `+0xD4`
/// when `+0xB0 <= +0x113C + 0x80C5B858`.
///
/// # Safety
/// Model, class and controller objects must be initialized.
///
/// # Confidence
/// high - the call sequence and comparison are literal.
pub unsafe fn fn_80c0b900(actor: usize) {
    vcall1(actor + 0x604, 0x1C, (actor + 0x604) as u32);
    platform::call1(0x8006_CDE0, actor as u32);
    platform::call1(0x8009_55F0, actor as u32);
    let selector = vcall1(actor + 0x60, 0x4C4, actor as u32) as u16 as i16;
    platform::call2(0x800A_A620, actor as u32, selector as i32 as u32);
    vcall1(actor + 0x60, 0x52C, actor as u32);
    vcall3(actor + 0x544, 0x28, (actor + 0x544) as u32, 0x581, 0);
    if platform::read_f32(actor + 0xB0)
        <= platform::read_f32(actor + 0x113C) + platform::read_f32(0x80C5_B858)
    {
        vcall2(actor + 0x60, 0xD4, actor as u32, 0x80C6_D2A4);
    }
}

