/// Emits the two-sided impact effects driven by the horizontal speed.
///
/// The x speed `+0xE8` selects between the two effect names at
/// `*(int *)(+0xAF0) + 0x2C` (below the threshold `0x80C57A1C`) and
/// `*(int *)(+0xAF0) + 0x28` (otherwise). A non-zero second argument enables
/// the landing effect at `+0x30`/`+0x34` chosen by the `+0xF4` switch, and
/// the third block at `+0x38` is spawned unconditionally through the
/// controller at `+0xD44`.
///
/// # Original
/// Synthetic base `0x80C00000`; this address is not a runtime address.
/// `FUN_80c18e40`, address `0x80C18E40`, size 380 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c18e40_FUN_80c18e40.c`.
///
/// # Arguments
/// * `actor` - actor with the effect slot `+0xAF0`.
/// * `landing` - non-zero enables the landing effect block.
///
/// # Side effects
/// Up to three effect spawns through `+0xC1C`, `0x8016C890` and `+0xD44`.
///
/// # Safety
/// The effect slot and both controllers must be valid.
///
/// # Confidence
/// high - every threshold, offset and argument order is literal.
pub unsafe fn fn_80c18e40(actor: usize, landing: i32) {
    let effects = platform::read_u32(actor + 0xAF0) as usize;
    let threshold = platform::read_f32(0x80C5_7A1C);
    if platform::read_f32(actor + 0xE8) <= threshold {
        if platform::read_f32(actor + 0xE8) < threshold
            && platform::read_u32(effects + 0x28) != 0
        {
            vcall6(
                actor + 0xC1C,
                0xA0,
                (actor + 0xC1C) as u32,
                platform::read_u32(effects + 0x2C),
                0,
                (actor + 0xAE4) as u32,
                0,
                0,
            );
        }
    } else {
        let name = platform::read_u32(effects + 0x28);
        if name != 0 {
            vcall6(
                actor + 0xC1C,
                0xA0,
                (actor + 0xC1C) as u32,
                name,
                0,
                (actor + 0xAE4) as u32,
                0,
                0,
            );
        }
    }

    if landing != 0 {
        if platform::read_f32(actor + 0xF4) < threshold {
            if platform::read_u32(effects + 0x30) != 0 {
                platform::call5(
                    0x8016_C890,
                    platform::read_u32(effects + 0x34),
                    0,
                    (actor + 0xAE4) as u32,
                    0,
                    0,
                );
            }
        } else {
            let name = platform::read_u32(effects + 0x30);
            if name != 0 {
                platform::call5(0x8016_C890, name, 0, (actor + 0xAE4) as u32, 0, 0);
            }
        }
    }

    let name = platform::read_u32(effects + 0x38);
    if name != 0 {
        vcall6(
            actor + 0xD44,
            0xA0,
            (actor + 0xD44) as u32,
            name,
            0,
            (actor + 0xAE4) as u32,
            0,
            0,
        );
    }
}

