/// `point` must be readable for two floats.
///
/// # Confidence
/// high - the four comparisons and the return values are literal.
pub unsafe fn fn_80c1d2d0(actor: usize, point: usize) -> u32 {
    let x = platform::read_f32(point);
    let y = platform::read_f32(point + 4);
    let origin_x = platform::read_f32(actor + 0x1228);
    let origin_y = platform::read_f32(actor + 0x122C);

    if origin_x + platform::read_f32(0x80C6_0104) <= x
        && x <= origin_x + platform::read_f32(0x80C6_010C)
        && origin_y + platform::read_f32(0x80C6_0108) <= y
        && y <= origin_y + platform::read_f32(0x80C6_0110)
    {
        1
    } else {
        0
    }
}

