// ---------------------------------------------------------------------------
// Wave 16 - companion spawners, phase/clip handlers, collision probes and
// aim/path helpers (0x80C050D0..0x80C56870)
// ---------------------------------------------------------------------------
//
// This pass fills the call-graph holes around the wave-15 constructors: the
// three companion spawners of each flying boss, the destructor wrappers for the
// controller arrays, the water/hit probes, the face-joint heading helper and
// the route-node selector. Every function below is a complete body from the
// export; calls that still have no Rust translation stay at their raw address.
//
// `// observed:` the export's `CONCAT44(0x43300000, x)` / `DAT_..._bias` pairs
// are the PowerPC compiler idiom for unsigned-int-to-double conversion. Their
// net value is exactly `x`, so the translations use an integer cast and keep
// the source counter/constant in a comment.

/// Calls a two-argument function that returns an `f32` in `f1`.
///
/// # Safety
/// `addr` must point to a PowerPC EABI function with that prototype.
unsafe fn call_f32_2(addr: usize, a: u32, b: u32) -> f32 {
    let f = crate::platform::guest_fn!(addr, fn(u32, u32) -> f32);
    f(a, b)
}

/// Calls vtable slot `slot` with one argument and returns the `f32` in `f1`.
///
/// # Safety
/// `vtable_object` must hold a readable vtable pointer and `slot` must point
/// to code with that prototype.
unsafe fn vcall_f32_arg1(vtable_object: usize, slot: usize, a: u32) -> f32 {
    let vtable = platform::read_u32(vtable_object) as usize;
    let function = platform::read_u32(vtable + slot) as usize;
    let f = crate::platform::guest_fn!(function, fn(u32) -> f32);
    f(a)
}

/// Destructor wrapper that releases the two controller arrays of an actor.
///
/// # Original
/// `// synthetic base: 0x80C00000` (analysis address, not a runtime address).
/// `FUN_80c11d60`, address `0x80C11D60`, size 140 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c11d60_FUN_80c11d60.c`.
///
/// # Arguments
/// * `this` - actor to clean up; a null pointer is returned unchanged.
/// * `free_it` - positive to release the actor after the arrays are cleared.
///
/// # Returns
/// `this`.
///
/// # Side effects
/// Releases the `0x128`-stride controller array at `+0xFBC` with
/// [`fn_80c005b0`], the `0x114`-stride array at `+0xEA8` with
/// [`fn_80c04cc0`], calls the base destructor `0x800A8B10`, and optionally
/// frees the object with `0x80162920`.
///
/// # Safety
/// `this` must be a live actor of the `0x1118` family or null.
///
/// # Confidence
/// high - the two array descriptors and the guard are literal.
pub unsafe fn fn_80c11d60(this: usize, free_it: i32) -> usize {
    if this != 0 {
        platform::call4(
            0x802D_CA98,
            (this + 0xFBC) as u32,
            fn_80c005b0 as *const () as usize as u32,
            0x128,
            1,
        );
        platform::call4(
            0x802D_CA98,
            (this + 0xEA8) as u32,
            fn_80c04cc0 as *const () as usize as u32,
            0x114,
            1,
        );
        platform::call2(0x800A_8B10, this as u32, 0);
        if free_it > 0 {
            platform::call1(0x8016_2920, this as u32);
        }
    }
    this
}

/// Per-frame handler that steps two embedded controllers and fires a state
/// notification when the `+0x588` clip has finished.
///
/// # Original
/// `// synthetic base: 0x80C00000` (analysis address, not a runtime address).
/// `FUN_80c2cc60`, address `0x80C2CC60`, size 152 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c2cc60_FUN_80c2cc60.c`.
///
/// # Arguments
/// * `actor` - actor with the animation pair `+0x548`/`+0x5C0` and the clip
///   object `+0x588`.
///
/// # Side effects
/// Steps both controllers, tests `0x80169020(+0x588)` and
/// `0x80166F20(+0x5C0, 0)`, writes the "done" byte `+0x634 = 1`, and sends
/// the state descriptor `0x80C6F1B0` through class slot `+0xD4`.
///
/// # Safety
/// Both controller objects and the class vtable must be initialized.
///
/// # Confidence
/// high - every slot, offset and store is literal.
pub unsafe fn fn_80c2cc60(actor: usize) {
    vcall1(actor + 0x548, 0x1C, (actor + 0x548) as u32);
    vcall1(actor + 0x5C0, 0x14, (actor + 0x5C0) as u32);

    if platform::call1(0x8016_9020, (actor + 0x588) as u32) != 0
        && platform::call2(0x8016_6F20, (actor + 0x5C0) as u32, 0) != 0
    {
        platform::write_u8(actor + 0x634, 1);
        class_call2(actor, 0xD4, actor as u32, 0x80C6_F1B0);
    }
}

/// Spawns the `0x128` companion object and places it above the actor.
///
/// # Original
/// `// synthetic base: 0x80C00000` (analysis address, not a runtime address).
/// `FUN_80c2e8d0`, address `0x80C2E8D0`, size 168 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c2e8d0_FUN_80c2e8d0.c`.
///
/// # Arguments
/// * `actor` - flying boss with the reference position `+0x788`/`+0x78C`
///   and the height `+0x7A0`.
///
/// # Side effects
/// Spawns type `0x128` at `(x, y, 3064)`, stores it at `+0x7A8`, writes the
/// owner word `+0x738`, and derives its `+0xB0` height from the result of
/// class slots `+0x3F4` and `+0x314` with the `0.7` constant at
/// `0x80C57F8C`.
///
/// # Safety
/// `actor` must be live and both class slots must return objects.
///
/// # Confidence
/// medium - the export drops the receiver argument of slot `+0x314`; the
/// translation passes the object returned by slot `+0x3F4`, by convention.
pub unsafe fn fn_80c2e8d0(actor: usize) {
    let mut point = crate::platform::GuestLocal::new( [0u32; 3]);
    point[0] = platform::read_u32(actor + 0x788);
    point[1] = platform::read_u32(actor + 0x78C);
    point[2] = platform::read_u32(0x80C5_7F88);

    let partner = platform::call6(
        0x8006_4680,
        0x128,
        actor as u32,
        0,
        point.as_ptr() as u32,
        0,
        0,
    ) as usize;
    platform::write_u32(actor + 0x7A8, partner as u32);
    platform::write_u32(partner + 0x738, actor as u32);

    let owner = class_call1(actor, 0x3F4, actor as u32) as usize;
    // observed: slot +0x314 returns f32 and is called without a printed
    // argument; the receiver is passed by convention.
    let value = vcall_f32_arg1(owner + 0x60, 0x314, owner as u32) as f64;
    let scale = platform::read_f32(0x80C5_7F8C) as f64;
    platform::write_f32(
        partner + 0xB0,
        platform::read_f32(actor + 0x7A0) + (scale * value) as f32,
    );
}

/// Seeds the module-global `0x19D` spawn table and emits its rows.
///
/// # Original
/// `// synthetic base: 0x80C00000` (analysis address, not a runtime address).
/// `FUN_80c2e980`, address `0x80C2E980`, size 312 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c2e980_FUN_80c2e980.c`.
///
/// # Arguments
/// * `actor` - flying boss whose `+0x788`/`+0x78C` position anchors the rows.
///
/// # Side effects
/// On the first call (`0x80C6F428 == 0`) fills four 3-float rows at
/// `0x80C6F430`:
/// `(x-184, z-112, 500)`, `(x+184, z-112, 500)`, `(x-208, z-112, 500)`,
/// `(x+208, z-112, 500)`, then sets the flag. Spawns `0x19D` once per row;
/// the row count comes from the four-word table at `0x80C57F90`
/// (`2, 2, 3, 4`) indexed by the value returned from `0x8005FEF0`.
///
/// # Returns
/// Nothing.
///
/// # Safety
/// `actor` must be live. `0x8005FEF0` is expected to return `1..=4`, the
/// range the original indexes without a bounds check.
///
/// # Confidence
/// high - every table word and store is quoted from the analysis image; the
/// `0x8005FEF0` role is unknown but its index use is literal.
pub unsafe fn fn_80c2e980(actor: usize) {
    let x = platform::read_f32(actor + 0x788);
    let z = platform::read_f32(actor + 0x78C);
    let center_offset = platform::read_f32(0x80C5_7FA0); // 184
    let outer_offset = platform::read_f32(0x80C5_7FA8); // 208
    let below = platform::read_f32(0x80C5_7F7C); // 112
    let height = platform::read_f32(0x80C5_7FA4); // 500

    if platform::read_u8(0x80C6_F428) == 0 {
        platform::write_f32(0x80C6_F434, z - below);
        platform::write_f32(0x80C6_F430, x - center_offset);
        platform::write_f32(0x80C6_F448, x - outer_offset);
        platform::write_f32(0x80C6_F43C, center_offset + x);
        platform::write_f32(0x80C6_F454, outer_offset + x);
        platform::write_f32(0x80C6_F438, height);
        platform::write_f32(0x80C6_F444, height);
        platform::write_f32(0x80C6_F450, height);
        platform::write_f32(0x80C6_F45C, height);
        platform::write_u8(0x80C6_F428, 1);
        platform::write_f32(0x80C6_F440, z - below);
        platform::write_f32(0x80C6_F44C, z - below);
        platform::write_f32(0x80C6_F458, z - below);
    }

    let players = call0_ret(0x8005_FEF0);
    let row_count = platform::read_i32(
        0x80C5_7F90 + players.wrapping_sub(1).wrapping_mul(4) as usize,
    );
    let mut i = 0i32;
    while i < row_count {
        platform::call6(
            0x8006_4680,
            0x19D,
            actor as u32,
            0,
            (0x80C6_F430 + i as usize * 0x0C) as u32,
            0,
            0,
        );
        i += 1;
    }
}

/// Spawns a seven-object arc of `0x12C` objects into `+0xD78`.
///
