    let partner = platform::call5(0x8006_4610, 0x12A, 0, point.as_ptr() as u32, 0, 0) as usize;
    platform::write_u32(actor + 0x7A8, partner as u32);
    platform::write_u32(partner + 0x738, actor as u32);
    platform::write_f32(
        partner + 0xAC,
        platform::read_f32(0x80C5_81F0) + platform::read_f32(actor + 0x788),
    );

    let owner = class_call1(actor, 0x3F0, actor as u32) as usize;
    let value = vcall_f32_arg1(owner + 0x60, 0x314, owner as u32) as f64;
    let scale = platform::read_f32(0x80C5_81F4) as f64;
