/// # Safety
/// The collider vtable and the two endpoints must be initialized.
///
/// # Confidence
/// high - the collider call and all stores are literal.
pub unsafe fn fn_80c543b0(magnitude: f64, actor: usize, direction: usize) {
    if platform::read_u32(actor + 0x78) & 8 != 0 {
        platform::call3(0x80C5_6240, actor as u32, 8, 1);
    }

    let hit = vcall3(
        actor + 4,
        0x24,
        actor as u32,
        (actor + 0x128) as u32,
        (actor + 0x134) as u32,
    );
    platform::write_u8(actor + 0x140, hit as u8);

    if hit as u8 != 0 {
        platform::write_f32(actor + 0x118, magnitude.abs() as f32);
        platform::write_u32(actor + 0x11C, platform::read_u32(direction));
        platform::write_u32(actor + 0x120, platform::read_u32(direction + 4));
        platform::write_u32(actor + 0x124, platform::read_u32(direction + 8));
        platform::write_f32(
            actor + 0xB8,
            platform::read_f32(actor + 0x134) - platform::read_f32(actor + 0xC),
        );
        platform::write_f32(
            actor + 0xBC,
            platform::read_f32(actor + 0x138) - platform::read_f32(actor + 0x10),
        );
        platform::write_f32(
            actor + 0xC0,
            platform::read_f32(actor + 0x13C) - platform::read_f32(actor + 0x14),
        );
        platform::write_u8(actor + 0x286, 0);
        platform::write_u8(actor + 0x285, 0);
    }
}

