/// # Side effects
/// Calls the `+0x394` controller tick, `0x800757B0` twice, class slot `+0xB0`
/// twice and increments `+0xEBC`.
///
/// # Safety
/// The actor, its two `+0xEC0` slot owners and the manager at `0x80429E00`
/// must be live.
///
/// # Confidence
/// medium - the two-slot loop and every offset are literal; the probe's
/// in/out argument split is reconstructed from the stack layout.
pub unsafe fn fn_80c04ef0(actor: usize) -> u32 {
    let tick_table = platform::read_u32(actor + 0x394) as usize;
    let tick = platform::read_u32(tick_table + 0x10) as usize;
    platform::call1(tick, (actor + 0x394) as u32);

    let probe_height = platform::read_f32(0x80C5_72F8); // 1500.0
    let manager = platform::read_u32(0x8042_9E00) as usize;

    let mut record = actor;
    let mut position = actor + 0x10E8;
    let mut owner = actor + 0xEC0;

    for _ in 0..2 {
        let mut input = crate::platform::GuestLocal::new( [
            platform::read_u32(record + 0x10E8),
            platform::read_u32(manager + 0x3C),
            probe_height.to_bits(),
        ]);
        let mut output = crate::platform::GuestLocal::new( [
            platform::read_u32(record + 0x10EC),
            input[0],
            input[1],
            input[2],
        ]);

        platform::call5(
            0x8007_57B0,
            input.as_mut_ptr() as u32,
            output.as_mut_ptr() as u32,
            platform::read_u8(actor + 0x38F) as u32,
            1,
            0xFFFF_FFFF,
        );

        platform::write_u32(record + 0x10EC, output[0]);
        vcall4(owner, 0xB0, owner as u32, position as u32, 0, 0);

        position += 0x0C;
        owner += 0x114;
        record += 0x0C;
    }

    platform::write_i32(actor + 0xEBC, platform::read_i32(actor + 0xEBC) + 1);
    1
}

