    let side = platform::call2(0x8009_6240, actor as u32, (actor + 0xAC) as u32) as u8;
    platform::write_u8(actor + 0x348, side);

    let base = call_f32_0(0x800B_30C0) as f64;
    let angle = vcall_f32_arg1(actor + 0x60, 0x624, actor as u32) as f64;
    platform::write_f32(actor + 0xE7C, angle as f32);

    let second = vcall_f32_arg1(actor + 0x60, 0x620, actor as u32) as f64;
    platform::write_f32(actor + 0xE8C, (base + second) as f32);

    let angle_again = vcall_f32_arg1(actor + 0x60, 0x624, actor as u32) as f64;
    platform::write_f32(actor + 0xE80, -angle_again as f32);

    let second_again = vcall_f32_arg1(actor + 0x60, 0x620, actor as u32) as f64;
    let side_signed = platform::read_u8(0x8042_C1A0 + side as usize) as i8 as i32;
    platform::write_f32(actor + 0xE90, (base - second_again) as f32);

    let bias = read_f64(0x80C5_8D88);
    let offset = int_to_double(side_signed as u32, bias) as f32;
    let sample = platform::read_f32(actor + 0xE8C + side as usize * 4);
    if (offset * (sample - platform::read_f32(actor + 0xAC))) as f64
        <= platform::read_f32(0x80C5_8D34) as f64
    {
        platform::write_u8(actor + 0x348, side ^ 1);
    }

    let zero = platform::read_f32(0x80C5_8D34); // 0.0
    let step = platform::read_f32(0x80C5_8D84); // 0.1
    let new_side = platform::read_u8(actor + 0x348);

    platform::write_u32(
        actor + 0xF4,
        platform::read_u32(actor + 0xE7C + new_side as usize * 4),
    );
    platform::write_f32(actor + 0xE8, zero);
    platform::write_f32(actor + 0x11C, step);
    platform::write_u32(actor + 0xE84, platform::read_u32(actor + 0xE8C));

    let mut value = platform::read_f32(actor + 0xE7C);
    'first: loop {
        loop {
            if !(platform::read_f32(actor + 0xE7C) <= zero) {
                break;
            }
            value += platform::read_f32(actor + 0x11C);
            platform::write_f32(
                actor + 0xE84,
                platform::read_f32(actor + 0xE84) - value,
            );
            if zero < value {
                break 'first;
            }
        }
        value -= platform::read_f32(actor + 0x11C);
        platform::write_f32(
            actor + 0xE84,
            platform::read_f32(actor + 0xE84) - value,
        );
        if !(zero <= value) {
            break;
        }
    }

    platform::write_u32(actor + 0xE88, platform::read_u32(actor + 0xE90));
    value = platform::read_f32(actor + 0xE80);
    'second: loop {
        loop {
            if !(platform::read_f32(actor + 0xE80) <= zero) {
                break;
            }
            value += platform::read_f32(actor + 0x11C);
            platform::write_f32(
                actor + 0xE88,
                platform::read_f32(actor + 0xE88) - value,
            );
            if zero < value {
                break 'second;
            }
        }
        value -= platform::read_f32(actor + 0x11C);
        platform::write_f32(
            actor + 0xE88,
            platform::read_f32(actor + 0xE88) - value,
        );
        if !(zero <= value) {
            break;
        }
    }

    platform::write_u16(actor + 0x500, 200);
    platform::write_i32(actor + 0x360, 1);
