/// Spawns a `0x129` guard and a ring of `299` effects in front of the actor.
///
/// The guard is placed at `+0x7A8` and its `+0x738` owner word is set to the
/// actor; its height is seeded from slot `+0x314` of the `+0x60` class. The
/// effect count comes from `0x8005FEF0()`; each effect is spaced by
/// `224 / (1 + count)` along X starting at `+0x788 - 112.0`, and its
/// `+0xB0`/`+0xEA4` heights are `+0x7A0 + 0.5 * slot(+0x314)`.
///
/// # Original
/// `// synthetic base: 0x80C00000` (analysis address, not a runtime address).
/// `FUN_80c30560`, address `0x80C30560`, size 512 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c30560_FUN_80c30560.c`.
///
/// # Arguments
/// * `actor` - actor with the `+0x788..+0x7A8` placement fields.
///
/// # Side effects
/// Spawns one `0x129` object and `count` objects of type `299`; writes
/// `+0x7A8`, `+0x738`, `+0xAC`, `+0xB0` and `+0xEA4`.
///
/// # Safety
/// The actor must be live and the spawners must accept the three-float
/// position.
///
/// # Confidence
/// medium - every field and constant is literal; the paired-single staging and
/// the two `0x80064610`/`0x80064680` argument orders are taken from the export.
pub unsafe fn fn_80c30560(actor: usize) {
    let mut position = crate::platform::GuestLocal::new( [0f32; 3]);
    position[0] = platform::read_f32(actor + 0x788);
    position[1] = platform::read_f32(actor + 0x78C);
    position[2] = platform::read_f32(0x80C5_809C); // 3064.0

    let guard = platform::call6(
        0x8006_4680,
        0x129,
        actor as u32,
        0,
        position.as_mut_ptr() as u32,
        0,
        0,
    ) as usize;
    platform::write_u32(actor + 0x7A8, guard as u32);
    platform::write_u32(guard + 0x738, actor as u32);

    let holder = vcall1(actor + 0x60, 0x3F0, actor as u32) as usize;
    let height = vcall_f32_0(holder + 0x60, 0x314);
    platform::write_f32(
        platform::read_u32(actor + 0x7A8) as usize + 0xB0,
        (platform::read_f32(actor + 0x7A0) as f64 + height as f64) as f32,
    );

    let count = call0_ret(0x8005_FEF0);
    let bias = read_f64(0x80C5_80A8); // 2^52 + 2^31
    let spread = platform::read_f32(0x80C5_80A0) * platform::read_f32(0x80C5_807C);
    let denominator =
        platform::read_f32(0x80C5_8098) + int_to_double(count, bias) as f32;
    let step = (spread as f64 / denominator as f64) as f32;
    let base = platform::read_f32(actor + 0x788) + platform::read_f32(0x80C5_8080)
        - spread * platform::read_f32(0x80C5_80A4);

    let mut index = 0i32;
    while index < count as i32 {
        position[0] = platform::read_f32(actor + 0x788);
        position[1] = platform::read_f32(actor + 0x78C);
        position[2] = platform::read_f32(0x80C5_809C);
        let effect =
            platform::call5(0x8006_4610, 299, 0, position.as_mut_ptr() as u32, 0, 0) as usize;

        let offset = int_to_double((index + 1) as u32, bias) as f32;
        let delta = (step as f64 * offset as f64) as f32;
        platform::write_f32(effect + 0xAC, (base as f64 + delta as f64) as f32);

        let height = vcall_f32_0(effect + 0x60, 0x314);
        platform::write_f32(
            effect + 0xB0,
            platform::read_f32(actor + 0x7A0)
                + (height as f64 * platform::read_f32(0x80C5_80A4) as f64) as f32,
        );
        let height = vcall_f32_0(effect + 0x60, 0x314);
        platform::write_f32(
            effect + 0xEA4,
            platform::read_f32(actor + 0x7A0)
                + (height as f64 * platform::read_f32(0x80C5_80A4) as f64) as f32,
        );
        index += 1;
    }
}

