pub unsafe fn fn_80c56910(this: usize) {
    if (platform::read_u32(this + 0x70) & 4) != 0 {
        platform::write_u32(this + 0x0C, platform::read_u32(this + 0x18));
    }
    if (platform::read_u32(this + 0x70) & 8) != 0 {
        platform::write_u32(this + 0x14, platform::read_u32(this + 0x20));
        platform::write_u32(this + 0x10, platform::read_u32(this + 0x1C));
    }
}

/// Probes the route tile selected by an input mask and publishes the result.
///
/// The route table and actor are the incoming `r3` and `r4`. The mask is mapped
/// by [`fn_80c56b20`] and its set-bit
/// index by [`fn_80c56b90`]. The selected row is resolved through `0x801002C0`
/// and tested with `0x800F57A0`; on success the flag byte at
/// `actor + bit + 0x1B4` is set and the index stored at `actor + bit * 4 +
/// 0x194`. The loop skips rows for which `0x800F9970` returns `1`.
///
/// # Original
/// `// synthetic base: 0x80C00000` (analysis address, not a runtime address).
/// `FUN_80c56ec0`, address `0x80C56EC0`, size 352 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c56ec0_FUN_80c56ec0.c`.
/// - Removed: the modelled `_savegpr_25` prologue call (`0x802DCD6C`) and the
///   `_restgpr_25` epilogue call (`0x802DCDB8`). The old `call_u64` split the
///   save stub's fake `r3:r4` return: `r3` is the route table (`mr r24,r3`) and
///   `r4` the actor (`mr r26,r4`). The tail `lbz r3,0x1B4(r31)` is the return.
///
/// # Arguments
/// * `table` - route table; the incoming `r3`.
/// * `actor` - route actor; the incoming `r4`.
/// * `index` - starting row index (`r5`).
/// * `mask` - input bit passed to the two mask helpers (`r6`).
///
/// # Returns
/// The selected slot's flag byte (`lbz r3,0x1B4(actor)`).
///
/// # Side effects
/// One row resolution, at most one collision test, and the flag-byte return.
///
/// # Safety
/// The route table and actor must be live; the row stride is five bytes.
///
/// # Confidence
/// medium - every offset and call is literal; the table/actor bindings are the
/// incoming `r3`/`r4`, and the `0x800F57A0` path recomputes its world base from
/// a reused local.
pub unsafe fn fn_80c56ec0(
    table: usize,
    actor: usize,
    index: i32,
    mask: u32,
) -> u32 {
    let world = platform::read_u32(0x8042_A18C) as usize;

    fn_80c56b20(actor as u32, mask);
    let bit = fn_80c56b90(actor as u32, mask) as usize;
    let slot = actor + bit * 4;

    let row = table + 0x0C;
    let row_base = platform::read_u32(row) as usize;
    let mut tile = platform::call2(
        0x8010_02C0,
        world as u32,
        (row_base + index as usize * 5) as u32,
    );

    if index == platform::read_i32(slot + 0x194) {
        platform::write_u8(actor + bit + 0x1B4, 0);
    }

    let flag_ptr = actor + bit + 0x1B4;
    if platform::read_u8(flag_ptr) == 0 {
        let world_base = world
            + platform::read_u32(world + 0x338C).wrapping_mul(0x16518) as usize
            + 0x3394;
        if platform::call3(0x800F_57A0, world_base as u32, tile, mask) != 0 {
            let mut next = index + 1;
            while next < platform::read_i32(table + 0x10) {
                let next_row = row_base + next as usize * 5;
                if platform::call1(0x800F_9970, next_row as u32) != 1 {
                    tile = platform::call2(0x8010_02C0, world as u32, next_row as u32);
                    let world_base = world
                        + platform::read_u32(world + 0x338C)
                            .wrapping_mul(0x16518) as usize
                        + 0x3394;
                    if platform::call3(
                        0x800F_57A0,
                        world_base as u32,
                        tile,
                        mask,
                    ) != 0
                    {
                        platform::write_u8(flag_ptr, 1);
                        platform::write_i32(slot + 0x194, next);
                    }
                    break;
                }
                next += 1;
            }
        }
    }

    platform::read_u8(flag_ptr) as u32
}

/// Resolves five `+0x30` links and recurses on the sixth.
///
/// Each node is probed with `(*(node + 0x30))->vtable[+0x0C]` through
/// [`chain_probe`]. The first node whose probe returns nonzero is returned.
/// When all five probes return zero, the helper recurses on the `+0x30` link
/// of the last probed node.
///
/// # Original
/// `// synthetic base: 0x80C00000` (analysis address, not a runtime address).
/// `FUN_80c18390`, address `0x80C18390`, size 224 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c18390_FUN_80c18390.c`.
///
/// # Arguments
/// * `node` - first object of the chain.
///
/// # Returns
/// The first object whose probe returned nonzero, or the recursive result.
///
/// # Side effects
/// Five virtual calls per body; one recursive body when all probes fail.
///
/// # Safety
/// Every `+0x30` link must be readable and hold a valid vtable pointer.
///
/// # Confidence
/// high - the body matches the translated [`fn_80c15a20`] after relocation.
pub unsafe fn fn_80c18390(node: usize) -> usize {
    let mut current = node;
    let mut probes = 0;
    while probes < 4 {
        if chain_probe(current) != 0 {
            return current;
        }
        current = platform::read_u32(current + 0x30) as usize;
        probes += 1;
    }
    if chain_probe(current) != 0 {
        current
    } else {
        fn_80c18390(platform::read_u32(current + 0x30) as usize)
    }
}

/// Compares the `:` suffix of an object name with a candidate suffix.
///
/// Both strings are cut at the first `:` (`0x3A`); the candidate side advances
/// only when a delimiter exists, the object side always advances. The two
/// remainders are compared with `0x802E1AB4`.
///
/// # Original
/// `// synthetic base: 0x80C00000` (analysis address, not a runtime address).
/// `FUN_80c18470`, address `0x80C18470`, size 136 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c18470_FUN_80c18470.c`.
///
/// # Arguments
/// * `object` - object whose vtable slot `+0x20` returns its name string.
/// * `name` - candidate `C` string.
///
/// # Returns
/// `true` when the two suffixes compare equal.
///
/// # Side effects
/// One virtual call and two string scans.
///
/// # Safety
/// `object` must hold a valid vtable and `name` must be a readable C string.
///
/// # Confidence
/// medium - the byte flow is literal; `0x802E1C40`/`0x802E1AB4` are named as
/// `strchr`/`strcmp` from their calling shape only.
pub unsafe fn fn_80c18470(object: usize, name: usize) -> bool {
    let mut rhs = name;
    let colon = platform::call2(0x802E_1C40, name as u32, 0x3A) as usize;
    if colon != 0 {
        rhs = colon + 1;
    }

    let lhs_text = vcall1(object, 0x20, object as u32) as usize;
    let lhs_colon = platform::call2(0x802E_1C40, lhs_text as u32, 0x3A) as usize;
    platform::call2(0x802E_1AB4, (lhs_colon + 1) as u32, rhs as u32) == 0
}

