/// Constructs a boss actor and publishes its five sub-objects and hit box.
///
/// The actor is the incoming `r3`. The body writes the motion/scale triple
/// (`+0xDC/+0xE0/+0xE4`), the heading pair, four motion words, and calls class
/// slot `+0x390`. It then walks the five-entry table at `0x80C61480` (three
/// words per entry, the first word is an animation handle) and initializes one
/// `0xA4`-byte sub-object per entry at the `+0xF94` array: `0x800E7880` samples
/// the model transform, `0x8008C3E0`/`0x8008C330` bind and finalize the
/// object, and the scale pair `+0x1C..+0x28` is written. Finally it fills the
/// `+0xF98` index table, builds the six-entry hit box at `+0x728..+0x740` from
/// the 16.16 constants at `0x80C6111C..0x80C61130`, hands the box to
/// `0x8006D090`, copies the render scales, clears the state block, queries
/// `0x800E77C0`, seeds the four `0x140`-byte counters, and unlocks.
///
/// # Original
/// `// synthetic base: 0x80C00000` (analysis address, not a runtime address).
/// `FUN_80c21bc0`, address `0x80C21BC0`, size 1056 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c21bc0_FUN_80c21bc0.c`.
/// - Removed: the modelled `_savegpr_23` prologue call (`0x802DCD64`) and the
///   `_restgpr_23` epilogue call (`0x802DCDB0`); the image reads the actor from
///   the incoming `r3` (`stw r5,0x76C(r3)`) and the tail `li r3,1` is the
///   return value.
///
/// # Arguments
/// * `this` - the actor; the incoming `r3`.
///
/// # Returns
/// `1`.
///
/// # Side effects
/// Several dozen field writes, one virtual call, five sub-object setups,
/// `0x8006D090`, `0x800E77C0`, and the tail returns `1`.
///
/// # Safety
/// `this` must be a live actor with a writable `+0xF94` array and the
/// `+0x1490` tail of fields.
///
/// # Confidence
/// medium - every store and loop bound is literal; the export's first ~86
/// lines are paired-single/GQR spill noise on dead stack slots, and the roles
/// of the sub-object fields are inferred from the repeating setup order.
pub unsafe fn fn_80c21bc0(this: usize) -> u32 {
    // unknown: the export opens with `unaff_GQR0`/`ldexpf` blocks that build
    // `local_8`/`local_18` from the paired-single registers `f30`/`f31` and
    // `ps30`/`ps31`. Those stack slots are never read, so this is register
    // save/restore noise, not game state; it is not translated.
    platform::write_u32(this + 0x76C, 0);
    platform::write_u32(this + 0x770, 1);

    // observed: 1.75 at 0x80C613D8 and 0.0 at 0x80C57CE8.
    let scale = platform::read_f32(0x80C6_13D8);
    platform::write_f32(this + 0xDC, scale);
    let side = platform::read_u8(0x8042_C1A1) as i8 as i32;
    let base = platform::read_f32(0x80C5_7CE8);
    platform::write_f32(this + 0xE0, scale);
    // observed: 1500.0 at 0x80C57CEC and 32.0 at 0x80C613E4.
    let motion_word = platform::read_u32(0x80C5_7CEC);
    let lift = platform::read_f32(0x80C6_13E4);
    platform::write_f32(this + 0xE4, scale);
    platform::write_f32(this + 0xD0, base);
    platform::write_f32(this + 0xD4, (lift as f64 * scale as f64) as f32);
    platform::write_f32(this + 0xD8, base);
    platform::write_u8(this + 0x348, 1);

    // observed: the signed halfword 0x3000 at 0x80C613E0 scaled by the
    // direction byte at 0x8042C1A1; the same expression is translated in
    // fn_80c27980.
    let heading = (read_i16(0x80C6_13E0) as i32 * side) as i16;
    platform::write_u16(this + 0x100, 0);
    platform::write_u16(this + 0x104, 0);
    platform::write_u16(this + 0x102, heading as u16);
    platform::write_u32(this + 0xB4, motion_word);
    platform::write_f32(this + 0x758, base);
    platform::write_f32(this + 0x764, base);
    platform::write_f32(this + 0x75C, base);
    platform::write_f32(this + 0x768, base);

    // virtual call on the object stored at +0x60.
    vcall0(this + 0x60, 0x390);

    // observed: five entries, three words each, at 0x80C61480.
    let count = platform::read_i32(0x80C6_147C);
    let mut entry = 0x80C6_1480usize;
    let mut offset = 0usize;
    let mut index = 0i32;
    while index < count {
        let mut scratch = crate::platform::GuestLocal::new( [0u32; 4]);
        platform::call4(
            0x800E_7880,
            scratch.as_mut_ptr() as u32,
            (this + 0x604) as u32,
            platform::read_u32(entry),
            0x8037_7DC8,
        );

        let array = platform::read_u32(this + 0xF94) as usize;
        let child = array + offset;
        platform::call3(0x8008_C3E0, child as u32, this as u32, 0x80C6_10F4);
        platform::write_u8(child + 0x9E, 1);
        platform::write_u8(child + 0xA0, platform::read_u8(this + 0x38F));
        platform::write_f32(child + 0x1C, base);
        platform::write_f32(child + 0x20, base);

        let child_scale = platform::read_f32(entry + 4);
        let scaled = (child_scale as f64 * scale as f64) as f32;
        platform::write_f32(child + 0x24, scaled);
        platform::write_f32(child + 0x28, scaled);
        platform::call1(0x8008_C330, child as u32);

        entry += 0x0C;
        offset += 0xA4;
        index += 1;
    }

    // observed: the export unrolls this index fill by eight and then runs the
    // remainder; the ascending writes are identical.
    let mut index = 0i32;
    while index < count {
        platform::write_i32(this + 0xF98 + index as usize * 4, index);
        index += 1;
    }

    platform::write_u32(this + 0x728, platform::read_u32(0x80C6_1118));
    // observed: the 16.16 box constants are divided and re-multiplied by 4096
    // (0x80C57CF0) and then scaled by +0xDC or +0xE0.
    let bias = read_f64(0x80C5_7CF8);
    let unit = platform::read_f32(0x80C5_7CF0);
    let scale_x = platform::read_f32(this + 0xDC);
    let scale_y = platform::read_f32(this + 0xE0);

    let left = (unit * ((int_to_double(platform::read_u32(0x80C6_111C), bias) as f32) / unit)
        * scale_x) as i32;
    platform::write_i32(this + 0x72C, left);
    let right = (unit * ((int_to_double(platform::read_u32(0x80C6_1120), bias) as f32) / unit)
        * scale_y) as i32;
    platform::write_i32(this + 0x730, right);
    let front = (unit * ((int_to_double(platform::read_u32(0x80C6_1124), bias) as f32) / unit)
        * scale_y) as i32;
    platform::write_i32(this + 0x734, front);
    platform::write_u32(this + 0x738, platform::read_u32(0x80C6_1128));
    let back = (unit * ((int_to_double(platform::read_u32(0x80C6_112C), bias) as f32) / unit)
        * scale_y) as i32;
    platform::write_i32(this + 0x73C, back);
    let top = (unit * ((int_to_double(platform::read_u32(0x80C6_1130), bias) as f32) / unit)
        * scale_x) as i32;
    platform::write_i32(this + 0x740, top);

    platform::call5(
        0x8006_D090,
        (this + 0x1EC) as u32,
        this as u32,
        (this + 0x728) as u32,
        0,
        (this + 0x738) as u32,
    );

    // observed: 0.0 at 0x80C57CE8 and 0.0 at 0x80C613E8/0x80C613EC.
    platform::write_f32(this + 0x320, platform::read_f32(0x80C5_7CE8));
    platform::write_f32(this + 0x324, platform::read_f32(0x80C5_7CE8));
    platform::write_f32(this + 0x318, platform::read_f32(0x80C6_13E8) * scale_x);
    platform::write_f32(this + 0x31C, platform::read_f32(0x80C6_13EC) * scale_y);

    platform::write_u8(this + 0x700, 1);
    platform::write_u8(this + 0x36D, 0);
    platform::write_u32(this + 0x77C, 0);
    platform::write_u16(this + 0x744, 0);
    platform::write_u8(this + 0x746, 0);
    platform::write_u32(this + 0x780, 0);
    platform::write_u16(this + 0x754, 0);
    platform::write_u32(this + 0x70C, 0);
    platform::write_u8(this + 0x718, 0);
    platform::write_u32(this + 0x784, 1);

    let queried = platform::call2(0x800E_77C0, 0x80C6_1D24, 0x80C6_1D28);
    platform::write_u32(this + 0x788, queried);

    // observed: the same counter word 0x14 (20) seeds four independent slots.
    let counter = platform::read_u32(0x80C6_1D9C);
    platform::write_u32(this + 0x10C0, counter);
    platform::write_u32(this + 0x1200, counter);
    platform::write_u32(this + 0x1340, counter);
    platform::write_u32(this + 0x1480, counter);

    1
}

