/// Copies a travel segment and updates the contact vector.
///
/// The function copies the two points into `+0x128..+0x13C`. When `enabled` is
/// zero or the two Z coordinates match, it optionally clears
/// `+0x10C..+0x114`, gates on the staging word `0x80C6C81C` (`5`/`4` against
/// the limit `+0x2C`), and asks the class slot `+0x24` whether the points are
/// acceptable. When they are, it builds the `+0xD0..+0xD8` contact vector, its
/// length at `+0xF4` through `0x801C14C0`, and accumulates it into
/// `+0x10C..+0x114`. If `0x800FA1D0` rejects the point, the vertical/horizontal
/// deltas fall back to the actor's `+0x44`/`+0x2C`/`+0x28` limits. When the two
/// points differ the X component of the contact vector is zero.
///
/// # Original
/// `// synthetic base: 0x80C00000` (analysis address, not a runtime address).
/// `FUN_80c54050`, address `0x80C54050`, size 864 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c54050_FUN_80c54050.c`.
///
/// # Arguments
/// * `actor` - actor with the position `+0x24` and the contact accumulator
///   `+0x10C`.
/// * `enabled` - when zero the Z equality and reset tests are skipped.
/// * `from` - first point (`x`, `y`, `z`).
/// * `to` - second point (`x`, `y`, `z`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Six copies into `+0x128..+0x13C`, the contact vector and length writes,
/// possible accumulator updates, and the class slot `+0x24` call.
///
/// # Safety
/// Both points must hold three floats, the class vtable at `+4` must be valid,
/// and `0x800FA1D0`/`0x801C14C0` must accept the values.
///
/// # Confidence
/// medium - the branch tree, every arithmetic step and both mode constants are
/// literal; the export's GQR staging is paired-single register noise, the roles
/// of `0x800FA1D0` and the class check are inferred, and the sibling
/// [`fn_80c52730`] shows the same contact shape with different offsets.
pub unsafe fn fn_80c54050(actor: usize, enabled: i32, from: usize, to: usize) {
    platform::write_u32(actor + 0x128, platform::read_u32(from));
    platform::write_u32(actor + 0x12C, platform::read_u32(from + 4));
    platform::write_u32(actor + 0x130, platform::read_u32(from + 8));
    platform::write_u32(actor + 0x134, platform::read_u32(to));
    platform::write_u32(actor + 0x138, platform::read_u32(to + 4));
    platform::write_u32(actor + 0x13C, platform::read_u32(to + 8));

    let zero = platform::read_f32(0x80C5_92B8); // observed: 0.0
    let from_x = platform::read_f32(from);
    let from_z = platform::read_f32(from + 8);

    if enabled == 0 || from_z == platform::read_f32(to + 8) {
        if enabled != 0 {
            platform::write_u32(actor + 0x10C, platform::read_u32(0x8037_7DC8));
            platform::write_u32(actor + 0x110, platform::read_u32(0x8037_7DCC));
            platform::write_u32(actor + 0x114, platform::read_u32(0x8037_7DD0));
        }

        let mode = platform::read_i32(0x80C6_C81C);
        if (mode != 5 || from_z <= platform::read_f32(actor + 0x2C))
            && (mode != 4 || platform::read_f32(actor + 0x2C) <= from_z)
        {
            let same_point = from_x == platform::read_f32(to)
                && platform::read_f32(from + 4) == platform::read_f32(to + 4)
                && from_z == platform::read_f32(to + 8);

            let accepted = if same_point {
                platform::write_u8(actor + 0x140, 1);
                true
            } else {
                let vtable = platform::read_u32(actor + 4) as usize;
                let function = platform::read_u32(vtable + 0x24) as usize;
                let verdict =
                    platform::call3(function, actor as u32, from as u32, to as u32) as u8;
                platform::write_u8(actor + 0x140, verdict);
                verdict != 0
            };

            if accepted {
                // The six contact components reset before the new vector.
                platform::write_f32(actor + 0xC4, zero);
                platform::write_f32(actor + 0xC8, zero);
                platform::write_f32(actor + 0xCC, zero);
                platform::write_f32(actor + 0xDC, zero);
                platform::write_f32(actor + 0xE0, zero);
                platform::write_f32(actor + 0xE4, zero);

                let mut dy = zero;
                let mut dz = zero;
                if platform::call1(0x800F_A1D0, from as u32) == 0 {
                    dy = platform::read_f32(from + 4) - platform::read_f32(actor + 0x28);
                    dz = if platform::read_f32(actor + 0x44) <= from_z {
                        from_z - platform::read_f32(actor + 0x44)
                    } else {
                        from_z - platform::read_f32(actor + 0x2C)
                    };
                }

                let dx = if same_point {
                    platform::read_f32(from) - platform::read_f32(actor + 0x24)
                } else {
                    zero
                };
                let dx_delta = dx - platform::read_f32(actor + 0xDC);
                let dy_delta = dy - platform::read_f32(actor + 0xE0);
                let dz_delta = dz - platform::read_f32(actor + 0xE4);

                platform::write_f32(actor + 0xD0, dx);
                platform::write_f32(actor + 0xD4, dy);
                platform::write_f32(actor + 0xD8, dz);
                platform::write_u8(actor + 0xF8, 1);

                let mut delta = crate::platform::GuestLocal::new( [dx_delta, dy_delta, dz_delta]);
                let length = call_f32_1(0x801C_14C0, delta.as_mut_ptr() as u32);

                platform::write_f32(actor + 0xF4, length);
                platform::write_f32(
                    actor + 0x10C,
                    platform::read_f32(actor + 0x10C) + dx,
                );
                platform::write_f32(
                    actor + 0x110,
                    platform::read_f32(actor + 0x110) + dy,
                );
                platform::write_f32(
                    actor + 0x114,
                    platform::read_f32(actor + 0x114) + dz,
                );
            }
        }
    } else {
        platform::write_u32(actor + 0x10C, platform::read_u32(0x8037_7DC8));
        platform::write_u32(actor + 0x110, platform::read_u32(0x8037_7DCC));
        platform::write_u32(actor + 0x114, platform::read_u32(0x8037_7DD0));
    }
}

