unsafe fn call_f64_3(addr: usize, value: f64, a: u32, b: u32, c: u32) -> u32 {
    let func = crate::platform::guest_fn!(addr, fn(f64, u32, u32, u32) -> u32);
    func(value, a, b, c)
}

/// Populates one animated Kameck route row from a scene list selected by name.
///
/// The body looks `route_name` up on the current scene (global `0x8042A18C`),
/// counts the list nodes, and only acts when at least three nodes exist. It
/// allocates one `0x18`-byte object with `0x802B9210`, builds the route
/// animation with `0x80105FD0` (row scale from the float table `0x80C6C1A8`,
/// the point count minus two, and the word at `0x80C6C390`), and stores the
/// handle in the row slot at `owner + index * 4 + 0x0C`.
///
/// It then walks the same list a second time. Each node payload is read with
/// `0x801006E0`; the first node seeds the animation with `0x80106D10`, every
/// following node becomes an intermediate key through `0x80106280`, the last
/// node terminates the track with `0x80106D30`, and `0x801062B0` finalizes
/// the animation.
///
/// # Original
/// `// synthetic base: 0x80C00000` (analysis address, not a runtime address).
/// `FUN_80c51520`, address `0x80C51520`, size 444 bytes,
/// `work/ghidra/rel-d_en_bossNP/export/80c51520_FUN_80c51520.c`.
///
/// # Arguments
/// * `owner` - route owner; the row handle lands at `owner + index * 4 + 0x0C`
///   (`+0x0C` for index 0 and `+0x10` for index 1, matching
///   [`fn_80c51460`]).
/// * `index` - row index; also selects the float at
///   `0x80C6C1A8 + index * 4`.
/// * `route_name` - name handle for the scene lookup `0x80100530`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Allocates `0x18` bytes, creates one animation object, performs two scene
/// lookups, and calls `0x801006E0`, `0x80106D10`, `0x80106280`, `0x80106D30`
/// and `0x801062B0` once per list node.
///
/// # Safety
/// The scene global and `route_name` must be valid, the list nodes must be
/// readable at `+0x08` and `+0x60`, and `owner` must cover `+0x10`.
///
/// # Confidence
/// medium - the two loops, every store and every call address are literal.
/// The export's `undefined8 uVar7` is the value left in `r3:r4` by the
/// `__savegprlr_27` prologue thunk `0x802DCD74`, so it is really the incoming
/// `(owner, index)` pair; the recovery is confirmed by the `+0x0C` row slot
/// agreeing with [`fn_80c51460`]. The roles of `0x80105FD0` and of the four
/// animation-key callees are inferred from their position in the loop.
pub unsafe fn fn_80c51520(owner: usize, index: u32, route_name: u32) {
    // observed: 0x8042A18C holds the current scene object (the same global is
    // read by game::bases::fn_8075ab00).
    let scene = platform::read_u32(0x8042_A18C);

    // Count the nodes of the list selected by `route_name`.
    let mut node = platform::call3(0x8010_0530, scene, route_name, 0) as usize;
    let mut count: i32 = 0;
    while node != 0 {
        count += 1;
        node = follow_relative(node, 0x60);
    }

    if count > 2 {
        // observed: 0x802B9210 is the default-heap `operator new(size)`.
        let memory = platform::call1(0x802B_9210, 0x18);

        // inferred: 0x80105FD0 builds the route animation from the per-row
        // scale, the fresh 0x18-byte block, the number of intermediate
        // points and the descriptor word at 0x80C6C390.
        let animation = if memory != 0 {
            call_f64_3(
                0x8010_5FD0,
                platform::read_f32(0x80C6_C1A8 + index as usize * 4) as f64,
                memory,
                (count - 2) as u32,
                platform::read_u32(0x80C6_C390),
            )
        } else {
            0
        };

        // The route row owns one handle per index; +0x0C is index 0 and +0x10
        // is index 1 (see fn_80c51460).
        let slot = owner + index as usize * 4;
        platform::write_u32(slot + 0x0C, animation);

        // Start the key track from the first node of the same list.
        let first = platform::call3(0x8010_0530, scene, route_name, 0) as usize;
        let mut scratch = crate::platform::GuestLocal::new( [0u32; 10]);
        platform::call3(
            0x8010_06E0,
            scene,
            follow_relative(first, 0x08) as u32,
            scratch.as_mut_ptr() as u32,
        );
        platform::call2(
            0x8010_6D10,
            platform::read_u32(slot + 0x0C),
            scratch.as_mut_ptr() as u32,
        );

        // Every further node appends one key; the final node terminates it.
        let mut node = follow_relative(first, 0x60);
        let mut frame: i32 = 0;
        while node != 0 {
            platform::call3(
                0x8010_06E0,
                scene,
                follow_relative(node, 0x08) as u32,
                scratch.as_mut_ptr() as u32,
            );
            if follow_relative(node, 0x60) == 0 {
                platform::call2(
                    0x8010_6D30,
                    platform::read_u32(slot + 0x0C),
                    scratch.as_mut_ptr() as u32,
                );
            } else {
                platform::call3(
                    0x8010_6280,
                    platform::read_u32(slot + 0x0C),
                    frame as u32,
                    scratch.as_mut_ptr() as u32,
                );
                frame += 1;
            }
            node = follow_relative(node, 0x60);
        }

        platform::call1(0x8010_62B0, platform::read_u32(slot + 0x0C));
    }
}

