/// manager's `+0x18` object and of clip `0x4EC` is `// unknown:` beyond its
/// shape.
pub unsafe fn fn_8009be40(this: usize) {
    let manager = platform::read_u32(C258_G_ACTOR_MANAGER) as usize;
    let watcher = platform::read_u32(manager + 0x18) as usize;
    if watcher != 0 {
        class_call1(watcher, 0x11C, watcher as u32);
    }

    crate::game::player::fn_80066a40(platform::read_u32(C258_G_ACTOR_MANAGER), 0);

    vcall3(this + 0x544, 0x24, (this + 0x544) as u32, C258_CLIP_4EC, 0);
}

