/// `0x80166310` - element advance by index on a filed animation block. The
/// original passes the blend weight in `f1` and the index in `r4`; the
/// translated wrapper drops `f1`, so slots 232 and 235 call the raw address.
const B259_FN_80166310: usize = 0x8016_6310;

/// `0x8008C380` - collision-area unregister on `+0x148`.
const B259_FN_COLLISION_UNREGISTER: usize = 0x8008_C380;

/// `0x8042C270` (`r2 - 0x6E10`) - the `0x4330_0000_8000_0000` double bias of
/// the PowerPC unsigned-int-to-double conversion, as an exact bit pattern.
const B259_F64_U32_BIAS: u64 = 0x4330_0000_8000_0000;

/// Converts the `+0x424` frame count with the `0x4330_0000` idiom used by slot
/// 235, then narrows it to the `f32` the three delta divisions consume.
#[inline]
fn b259_count_to_f32(count: u32) -> f32 {
    let biased = 0x4330_0000_0000_0000u64 | ((count ^ 0x8000_0000) as u64);
    (f64::from_bits(biased) - f64::from_bits(B259_F64_U32_BIAS)) as f32
}

